insert into public.questions (id, subject_id, grade, difficulty, standard, skill, prompt, choices, answer_index, explanation, xp, kind, payload) values
('19b6234f-70cb-411c-a616-6ef5cde6627a', 'science', 'K', 1, NULL, 'K.observation', 'Which ball has a different color from the other two?', '["A","B","C"]', 2, 'A and B are red. C is blue, so C has a different color.', 10, 'mcq', '{"observation":{"title":"Look at the balls","context":"Look closely. Which things are the same? Which thing is different?","format":"objects","columns":["Color"],"rows":[{"label":"A","values":["Red"],"symbol":"red-ball"},{"label":"B","values":["Red"],"symbol":"red-ball"},{"label":"C","values":["Blue"],"symbol":"blue-ball"}]}}'),
('0c12dd00-650e-40b3-adb5-8b6467bca705', 'science', 'K', 1, NULL, 'K.observation', 'Which two balls have the same color?', '["A and B","A and C","B and C"]', 0, 'A and B are both red. We can compare things by looking at their colors.', 10, 'mcq', '{"observation":{"title":"Look at the balls","context":"Look closely. Which things are the same? Which thing is different?","format":"objects","columns":["Color"],"rows":[{"label":"A","values":["Red"],"symbol":"red-ball"},{"label":"B","values":["Red"],"symbol":"red-ball"},{"label":"C","values":["Blue"],"symbol":"blue-ball"}]}}'),
('91787c6c-99f0-4384-a019-6a067011dbd5', 'science', '1', 1, NULL, '1.observation', 'How many days in this record were rainy at noon?', '["2","3","5"]', 1, 'Tuesday, Wednesday, and Friday show rain. That makes 3 rainy observations.', 10, 'mcq', '{"observation":{"title":"Our weather week","context":"A class looked outside at noon each day and made this picture record.","format":"weather","columns":["Weather"],"rows":[{"label":"Monday","values":["Sunny"],"symbol":"sun"},{"label":"Tuesday","values":["Rainy"],"symbol":"rain"},{"label":"Wednesday","values":["Rainy"],"symbol":"rain"},{"label":"Thursday","values":["Sunny"],"symbol":"sun"},{"label":"Friday","values":["Rainy"],"symbol":"rain"}]}}'),
('1638bf4b-b85b-41d6-a833-991e50585d3f', 'science', '1', 1, NULL, '1.observation', 'Which two days show sunny weather at noon?', '["Tuesday and Friday","Wednesday and Thursday","Monday and Thursday"]', 2, 'The sunny pictures are on Monday and Thursday. The record only tells us about the time the class looked.', 10, 'mcq', '{"observation":{"title":"Our weather week","context":"A class looked outside at noon each day and made this picture record.","format":"weather","columns":["Weather"],"rows":[{"label":"Monday","values":["Sunny"],"symbol":"sun"},{"label":"Tuesday","values":["Rainy"],"symbol":"rain"},{"label":"Wednesday","values":["Rainy"],"symbol":"rain"},{"label":"Thursday","values":["Sunny"],"symbol":"sun"},{"label":"Friday","values":["Rainy"],"symbol":"rain"}]}}'),
('9646e85e-a149-4ae1-a634-2d384b64882a', 'science', '2', 2, NULL, '2.observation', 'Which material let the most light through in these observations?', '["Clear plastic","Wax paper","Cardboard","They all let through the same amount"]', 0, 'The clear plastic produced bright light on the screen. Wax paper produced dim light, and cardboard produced none.', 10, 'mcq', '{"observation":{"title":"What happened to the light?","context":"In this sample investigation, a class used the same flashlight at the same distance. They changed the material in front of it.","format":"table","columns":["Light seen on screen"],"rows":[{"label":"Clear plastic","values":["Bright light"]},{"label":"Wax paper","values":["Dim light"]},{"label":"Cardboard","values":["No light"]}]}}'),
('5e1bd648-5b22-48c3-ad7d-b6e5cf62251e', 'science', '2', 2, NULL, '2.observation', 'What did the class change between these tests?', '["The distance from the flashlight","The material in front of the flashlight","The time of day","The screen size"]', 1, 'The notes say the flashlight and distance stayed the same. The material was the thing that changed.', 10, 'mcq', '{"observation":{"title":"What happened to the light?","context":"In this sample investigation, a class used the same flashlight at the same distance. They changed the material in front of it.","format":"table","columns":["Light seen on screen"],"rows":[{"label":"Clear plastic","values":["Bright light"]},{"label":"Wax paper","values":["Dim light"]},{"label":"Cardboard","values":["No light"]}]}}'),
('4e2ff0b7-c77f-40a6-aaf1-4021975ebaea', 'science', '3', 2, NULL, '3.observation', 'Which pattern is shown in these trials?', '["Higher ramps led to shorter distances","All distances were equal","Higher ramps led to longer distances","The low ramp sent the car farthest"]', 2, 'The recorded distance increases from 40 to 65 to 90 cm as ramp height increases. This describes these trials, not every possible car and ramp.', 10, 'mcq', '{"observation":{"title":"A toy car investigation","context":"These sample results use the same car and floor. The car was released without a push from ramps of three heights.","format":"bars","columns":["Distance traveled"],"unit":"cm","scaleMax":100,"rows":[{"label":"Low ramp","values":["40 cm"],"amount":40},{"label":"Middle ramp","values":["65 cm"],"amount":65},{"label":"High ramp","values":["90 cm"],"amount":90}]}}'),
('6affa345-5474-4190-a102-6b591fb76190', 'science', '3', 2, NULL, '3.observation', 'Which detail helps make this a fair comparison of ramp heights?', '["The ramps have different heights","The distances are different","The bars have labels","The same car and floor were used"]', 3, 'Keeping the car and floor the same helps the class compare the effect of changing ramp height.', 10, 'mcq', '{"observation":{"title":"A toy car investigation","context":"These sample results use the same car and floor. The car was released without a push from ramps of three heights.","format":"bars","columns":["Distance traveled"],"unit":"cm","scaleMax":100,"rows":[{"label":"Low ramp","values":["40 cm"],"amount":40},{"label":"Middle ramp","values":["65 cm"],"amount":65},{"label":"High ramp","values":["90 cm"],"amount":90}]}}'),
('16a39c8a-bb41-4ea6-a17c-4994868eb3cf', 'science', '4', 2, NULL, '4.observation', 'Which conclusion is best supported by the results?', '["The foam-wrapped cup had the smallest temperature drop","The paper-wrapped cup stayed warmest","All cups ended at the same temperature","Cloth made the water hotter than it started"]', 0, 'The foam-wrapped cup changed from 50°C to 47°C, a drop of 3°C. The cloth and paper cups dropped 6°C and 10°C.', 10, 'mcq', '{"observation":{"title":"Comparing cup covers","context":"An adult prepared equal amounts of warm water in identical cups. Each started at 50°C. The cups stayed in the same room for 10 minutes. Only the wrapping material changed. These are sample results.","format":"table","columns":["Start","After 10 min"],"rows":[{"label":"Paper wrap","values":["50°C","40°C"]},{"label":"Cloth wrap","values":["50°C","44°C"]},{"label":"Foam wrap","values":["50°C","47°C"]}]}}'),
('d7f88466-47b6-4672-a09f-6ea045b12b58', 'science', '4', 2, NULL, '4.observation', 'Why did all cups start with the same amount and temperature of water?', '["To make every final temperature identical","To make the comparison of wrapping materials fairer","To make the experiment finish instantly","To prove that no heat could escape"]', 1, 'Keeping the starting conditions alike helps the class investigate wrapping material instead of differences in the water at the start.', 10, 'mcq', '{"observation":{"title":"Comparing cup covers","context":"An adult prepared equal amounts of warm water in identical cups. Each started at 50°C. The cups stayed in the same room for 10 minutes. Only the wrapping material changed. These are sample results.","format":"table","columns":["Start","After 10 min"],"rows":[{"label":"Paper wrap","values":["50°C","40°C"]},{"label":"Cloth wrap","values":["50°C","44°C"]},{"label":"Foam wrap","values":["50°C","47°C"]}]}}'),
('1ee0017b-0517-4d54-a54f-286631740e00', 'science', '5', 2, NULL, '5.observation', 'Which claim is supported by all three trials?', '["The car always moved at the same speed","The ramp height caused every difference","The car traveled farthest on tile in these tests","All three surfaces produced equal distances"]', 2, 'Every tile distance is greater than every cardboard or carpet distance. These results support a claim about distance in these tests; speed was not measured.', 10, 'mcq', '{"observation":{"title":"Does the surface matter?","context":"A team released the same toy car from the same ramp height without pushing it. They measured the distance after the car reached each surface. Each surface was tested three times. These are sample results.","format":"table","columns":["Trial 1","Trial 2","Trial 3"],"rows":[{"label":"Carpet","values":["31 cm","33 cm","32 cm"]},{"label":"Cardboard","values":["54 cm","57 cm","55 cm"]},{"label":"Tile","values":["92 cm","96 cm","94 cm"]}]}}'),
('bd69fb99-e063-44d1-ab4c-02ad188c1bc1', 'science', '5', 2, NULL, '5.observation', 'Why are repeated trials useful here?', '["They guarantee that measurements cannot be wrong","They replace the need to keep the ramp height the same","They prove the result for every kind of toy car","They show whether a pattern is consistent across attempts"]', 3, 'The distances vary a little, but the same surface pattern appears in every trial. Repeating tests helps evaluate consistency without guaranteeing perfect results.', 10, 'mcq', '{"observation":{"title":"Does the surface matter?","context":"A team released the same toy car from the same ramp height without pushing it. They measured the distance after the car reached each surface. Each surface was tested three times. These are sample results.","format":"table","columns":["Trial 1","Trial 2","Trial 3"],"rows":[{"label":"Carpet","values":["31 cm","33 cm","32 cm"]},{"label":"Cardboard","values":["54 cm","57 cm","55 cm"]},{"label":"Tile","values":["92 cm","96 cm","94 cm"]}]}}')
